export fn langtons_ant(v:[*]const i64,n:usize)i64{if(n!=1)return -1;const steps=v[0];if(steps<0 or steps>6)return -1;var b:[25]bool=@splat(true);var x:i64=2;var y:i64=2;var d:i64=3;const dx=[_]i64{-1,0,1,0};const dy=[_]i64{0,1,0,-1};for(0..@as(usize,@intCast(steps)))|_|{const old:usize=@intCast(x*5+y);d=if(b[old])@rem(d+1,4) else @rem(d+3,4);x+=dx[@intCast(d)];y+=dy[@intCast(d)];b[old]=!b[old];}var mask:i64=0;for(0..25)|i|{if(!b[i])mask|=@as(i64,1)<<@intCast(i);}return mask|((x*5+y)<<25)|(d<<30);}
